"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["10603"],{90181(e){e.exports=JSON.parse('{"id":"F414","slug":"cointegration-half-life","name":"Cointegration: Hedge Ratio, Spread Z-Score and Half-Life","subject":"Quantitative Finance","section":"Quant","topic":"Cointegration","level":"Intermediate","aliases":["cointegration","Engle Granger","mean reversion of spread","half-life of mean reversion"],"formula":{"latex":"\\\\beta=\\\\frac{Cov(Y,X)}{Var(X)},\\\\; s_{t}=Y_{t}-\\\\beta X_{t}-\\\\alpha,\\\\; s_{t}=\\\\phi s_{t-1}+\\\\varepsilon,\\\\; t_{1/2}=\\\\frac{-\\\\ln 2}{\\\\ln\\\\phi}","also":[],"text":"Hedge ratio beta = Covariance(Y, X) / Variance(X); Spread = Y - beta x X - alpha; Fit spread today = phi x spread yesterday; Half-life = -ln 2 / ln(phi)"},"symbols":[{"symbol":"Y, X","meaning":"Two price series that may move together","unit":"money"},{"symbol":"beta","meaning":"Hedge ratio from regressing Y on X","unit":"number"},{"symbol":"alpha","meaning":"Intercept of that regression","unit":"money"},{"symbol":"phi","meaning":"Autoregressive coefficient of the spread. Between 0 and 1 means it reverts","unit":"number"},{"symbol":"t_1/2","meaning":"Half-life: periods for a gap to close by half","unit":"periods"}],"when_to_use":"Use it to test whether two prices share a long-run link. Each price may wander, but if a mix of them is stable the pair is cointegrated and the gap tends to close. The half-life says how fast. A full test also needs a unit-root test on the spread (Engle-Granger), which this calculator does not run, so treat the result as a screen and not proof.","worked_example":{"problem":"Two price series of 30 observations each are given in the calculator. Regress Y on X, build the spread, find its latest z-score and the half-life.","inputs":{"y":[85,84.53,84.11,82.47,81.67,81.22,80.92,83.12,83.07,81.74,82.47,83.14,83.37,81.24,81.47,83.47,80.39,80.39,77.58,75.22,73.75,73.55,70.58,71.01,71.55,71.03,67.61,66.61,66.83,67.67],"x":[50,50.3,50.03,49.14,48.68,47.69,47.75,49.09,48.6,47.98,48.47,48.82,48.93,48,47.97,48.66,47.32,46.86,44.96,43.67,41.83,41.59,40.33,40.6,40.76,40.57,38.05,37.51,37.46,37.58]},"steps":[{"label":"Hedge ratio = Cov(Y, X) / Var(X)","working":null,"value":"1.3940"},{"label":"Intercept = mean(Y) - beta x mean(X)","working":null,"value":"14.7347"},{"label":"Spread series","working":null,"value":"0.56, -0.32, -0.37, -0.77, -0.93, 0.00, -0.38, -0.05, 0.59, 0.12, 0.17, 0.35, 0.43, -0.41, -0.14, 0.90, -0.31, 0.33, 0.17, -0.39, 0.70, 0.84, -0.38, -0.32, -0.00, -0.26, -0.17, -0.41, -0.12, 0.55"},{"label":"Latest z-score = (last spread - mean) / sd","working":null,"value":"1.181"},{"label":"phi = Cov(spread_t, spread_t-1) / Var(spread_t-1)","working":null,"value":"0.1321"},{"label":"Half-life = -ln 2 / ln(phi)","working":"-ln(2) / ln(0.132143)","value":"0.34"}],"answer":"The hedge ratio is 1.3940 and the intercept is 14.7347. The latest spread sits 1.181 standard deviations from its mean. The spread\'s persistence is 0.1321, so a gap closes by half in 0.34 periods."},"calculator":{"available":true,"inputs":[{"id":"y","label":"Prices of Y, oldest first","unit":"money","type":"list","default":[85,84.53,84.11,82.47,81.67,81.22,80.92,83.12,83.07,81.74,82.47,83.14,83.37,81.24,81.47,83.47,80.39,80.39,77.58,75.22,73.75,73.55,70.58,71.01,71.55,71.03,67.61,66.61,66.83,67.67],"hint":""},{"id":"x","label":"Prices of X, same dates","unit":"money","type":"list","default":[50,50.3,50.03,49.14,48.68,47.69,47.75,49.09,48.6,47.98,48.47,48.82,48.93,48,47.97,48.66,47.32,46.86,44.96,43.67,41.83,41.59,40.33,40.6,40.76,40.57,38.05,37.51,37.46,37.58],"hint":""}],"checks":[{"expr":"count(x)==count(y) and count(x)>=10","message":"Enter two lists of the same length, at least 10 observations."}],"steps":[{"id":"beta","label":"Hedge ratio = Cov(Y, X) / Var(X)","expr":"cov(y, x)/var(x)","format":"num4"},{"id":"alpha","label":"Intercept = mean(Y) - beta x mean(X)","expr":"mean(y)-beta*mean(x)","format":"num4"},{"id":"sp","label":"Spread series","expr":"minus(minus(y, scale(x, beta)), alpha)","format":"list2"},{"id":"z","label":"Latest z-score = (last spread - mean) / sd","expr":"(last(sp,1)[0]-mean(sp))/sd(sp)","format":"num3"},{"id":"phi","label":"phi = Cov(spread_t, spread_t-1) / Var(spread_t-1)","expr":"cov(sp[1:], sp[:-1])/var(sp[:-1])","format":"num4"},{"id":"hl","label":"Half-life = -ln 2 / ln(phi)","expr":"-ln(2)/ln(phi)","format":"num2"}],"results":["beta","z","phi","hl"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"beta":1.3940101065255734,"alpha":14.734715440348033,"z":1.1812497056543243,"phi":0.13214273941262053,"hl":0.3424855827934402}},"finder":{"finds":"Whether a pair behaves like a stable spread and how fast it reverts","needs":"Two aligned price lists"},"related":[{"slug":"pairs-trade-sizing","name":"Pairs Trade Sizing and Reversion Profit"},{"slug":"ou-process-moments","name":"Mean-Reverting (Ornstein-Uhlenbeck) Process Moments"},{"slug":"regression-line","name":"Regression Line (Alpha and Beta)"}],"related_ids":["F415","F399","F051"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>\u03B2</mi><mo>=</mo><mfrac><mrow><mi>C</mi><mi>o</mi><mi>v</mi><mo stretchy=\\"false\\">(</mo><mi>Y</mi><mo separator=\\"true\\">,</mo><mi>X</mi><mo stretchy=\\"false\\">)</mo></mrow><mrow><mi>V</mi><mi>a</mi><mi>r</mi><mo stretchy=\\"false\\">(</mo><mi>X</mi><mo stretchy=\\"false\\">)</mo></mrow></mfrac><mo separator=\\"true\\">,</mo><mtext>\u2005\u200A</mtext><msub><mi>s</mi><mi>t</mi></msub><mo>=</mo><msub><mi>Y</mi><mi>t</mi></msub><mo>\u2212</mo><mi>\u03B2</mi><msub><mi>X</mi><mi>t</mi></msub><mo>\u2212</mo><mi>\u03B1</mi><mo separator=\\"true\\">,</mo><mtext>\u2005\u200A</mtext><msub><mi>s</mi><mi>t</mi></msub><mo>=</mo><mi>\u03D5</mi><msub><mi>s</mi><mrow><mi>t</mi><mo>\u2212</mo><mn>1</mn></mrow></msub><mo>+</mo><mi>\u03B5</mi><mo separator=\\"true\\">,</mo><mtext>\u2005\u200A</mtext><msub><mi>t</mi><mrow><mn>1</mn><mi mathvariant=\\"normal\\">/</mi><mn>2</mn></mrow></msub><mo>=</mo><mfrac><mrow><mo>\u2212</mo><mi>ln</mi><mo>\u2061</mo><mn>2</mn></mrow><mrow><mi>ln</mi><mo>\u2061</mo><mi>\u03D5</mi></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">\\\\beta=\\\\frac{Cov(Y,X)}{Var(X)},\\\\; s_{t}=Y_{t}-\\\\beta X_{t}-\\\\alpha,\\\\; s_{t}=\\\\phi s_{t-1}+\\\\varepsilon,\\\\; t_{1/2}=\\\\frac{-\\\\ln 2}{\\\\ln\\\\phi}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"coefficient-of-variation","name":"Coefficient of Variation"},"next":{"slug":"collar-payoff","name":"Collar (Protective Put Financed by a Covered Call)"},"lesson":null,"total":522}')}}]);